<?php

namespace App\Models;

use App\Models\Concerns\Audited;
use App\Support\Audit;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Str;

/**
 * App\Models\QrCode
 *
 * A QR code generated by the system for the inside of a PUJ. What is printed in the code is
 * {@see scanUrl()}: a link that, opened on a signed-in phone, verifies the commuter for one fare.
 *
 * @property int $id
 * @property string $token
 * @property bool $is_active
 * @property int|null $created_by
 * @mixin \Eloquent
 */
class QrCode extends Model
{
    use Audited;
    use HasFactory;

    protected $fillable = ['token', 'is_active', 'created_by'];

    protected $casts = ['is_active' => 'boolean'];

    protected static function booted(): void
    {
        static::creating(function (QrCode $code) {
            $code->token = $code->token ?: Str::random(40);
        });
    }

    public function scans()
    {
        return $this->hasMany(QrScan::class);
    }

    /** The address encoded in the QR image. */
    public function scanUrl(): string
    {
        return route('ride.scan.link', $this->token);
    }

    /**
     * Find the code behind whatever a scanner read: the full link, or just the token typed in by hand.
     * Only an active code counts.
     */
    public static function fromScanned(?string $scanned): ?self
    {
        $scanned = trim((string) $scanned);

        if ($scanned === '') {
            return null;
        }

        // The link ends in the token; so does a bare token.
        $token = preg_match('~([A-Za-z0-9]{40})/?(?:[?#].*)?$~', $scanned, $m) ? $m[1] : $scanned;

        return static::where('token', $token)->where('is_active', true)->first();
    }

    /** How the code is named on screen: there is no label, only its number. */
    public function name(): string
    {
        return 'Code #'.$this->id;
    }

    protected function auditCategory(): string
    {
        return Audit::FLEET;
    }

    protected function auditAttributes(): array
    {
        return ['is_active'];
    }

    protected function auditLabel(): string
    {
        return 'QR code #'.$this->getKey();
    }
}
